with months as (select distinct cast(date_trunc('month', date_day) as date) as month_start from {{ ref('time_spine') }}), month_ends as (select month_start, cast(month_start + interval '1 month' - interval '1 day' as date) as month_end from months) select distinct me.month_start, c.member_id from {{ ref('cards') }} c join month_ends me on c.card_type in ('悦享年卡','家庭季卡') and c.valid_from is not null and c.valid_until is not null and c.valid_from < c.valid_until and (c.ended_at is null or (c.ended_at > c.valid_from and c.ended_at < c.valid_until)) and c.valid_from <= me.month_end and me.month_end < c.valid_until and (c.ended_at is null or me.month_end < c.ended_at)